// Clinical model: diagnosis catalog, diagnosis-to-treatment, configurable stage tracker, sessions, files.
check('Catálogo de diagnósticos poblado por categoría',fn()=>(int)DB::query('SELECT COUNT(DISTINCT category) FROM diagnosis_catalog')->fetchColumn()>=6);
