check('Diagnóstico registrado con superficies múltiples',fn()=>(int)DB::query('SELECT COUNT(*) FROM clinical_diagnosis_surfaces WHERE clinical_diagnosis_id=?',[$diag])->fetchColumn()===2);
check('Diagnóstico aparece activo para el paciente',fn()=>(bool)array_filter(Treatment::patientDiagnoses((int)DB::one('SELECT id FROM clinical_records WHERE patient_id=?',[$pid])['id']),fn($d)=>(int)$d['id']===$diag && $d['status']==='active'));
check('Pieza FDI inexistente rechazada en diagnóstico',fn()=>rejects(fn()=>Treatment::diagnose(['patient_id'=>$pid,'tooth_fdi'=>99,'diagnosis_id'=>$pulpitis])));
check('Diagnóstico inactivo o inexistente rechazado',fn()=>rejects(fn()=>Treatment::diagnose(['patient_id'=>$pid,'tooth_fdi'=>36,'diagnosis_id'=>999999])));
check('Superficie no válida rechazada en diagnóstico',fn()=>rejects(fn()=>Treatment::diagnose(['patient_id'=>$pid,'tooth_fdi'=>36,'diagnosis_id'=>$pulpitis,'surfaces'=>['raiz']])));
$endoPlan=Clinic::plan(['patient_id'=>$pid,'dentist_id'=>$dentist,'name'=>'Plan Endodoncia Test','treatment_id'=>$treatment,'tooth_fdi'=>36,'clinical_diagnosis_id'=>$diag,'specialty'=>'endodontics','priority'=>'high','justification'=>'Pulpitis irreversible ficticia','estimated_sessions'=>2]);
$endoItem=(int)DB::query('SELECT id FROM treatment_plan_items WHERE plan_id=?',[$endoPlan])->fetchColumn();
check('Propuesta de endodoncia siembra las 12 etapas del protocolo',fn()=>(int)DB::query('SELECT COUNT(*) FROM treatment_stages WHERE treatment_plan_item_id=?',[$endoItem])->fetchColumn()===12);
check('Etapas creadas en orden con estado pendiente',fn()=>DB::one('SELECT stage_key,status FROM treatment_stages WHERE treatment_plan_item_id=? AND sort_order=0',[$endoItem])===['stage_key'=>'evaluacion','status'=>'pending']);
check('Nuevo tratamiento inicia en estado clínico propuesto',fn()=>DB::one('SELECT clinical_status FROM treatment_plan_items WHERE id=?',[$endoItem])['clinical_status']==='proposed');
$generalItem=Clinic::planItem(['treatment_id'=>$treatment,'specialty'=>'general'],$endoPlan);
check('Especialidad sin protocolo configurado no siembra etapas',fn()=>(int)DB::query('SELECT COUNT(*) FROM treatment_stages WHERE treatment_plan_item_id=?',[$generalItem])->fetchColumn()===0);
check('Progreso inicial en cero sin etapas completadas',fn()=>Treatment::progress($endoItem)===['total'=>12,'completed'=>0,'percent'=>0,'has_stages'=>true]);
$apertura=(int)DB::query('SELECT id FROM treatment_stages WHERE treatment_plan_item_id=? AND stage_key=?',[$endoItem,'apertura'])->fetchColumn();
Treatment::stage(['id'=>$apertura,'status'=>'completed','procedures'=>'Apertura cameral ficticia']);
check('Etapa completada registra fecha de inicio y fin',fn()=>(bool)DB::one('SELECT id FROM treatment_stages WHERE id=? AND started_at IS NOT NULL AND completed_at IS NOT NULL',[$apertura]));
$irrigacion=(int)DB::query('SELECT id FROM treatment_stages WHERE treatment_plan_item_id=? AND stage_key=?',[$endoItem,'irrigacion'])->fetchColumn();
Treatment::stage(['id'=>$irrigacion,'status'=>'not_applicable']);
check('Etapa no aplicable se excluye del denominador de avance',fn()=>Treatment::progress($endoItem)===['total'=>11,'completed'=>1,'percent'=>9,'has_stages'=>true]);
check('Etapa inexistente rechazada',fn()=>rejects(fn()=>Treatment::stage(['id'=>999999,'status'=>'completed'])));
$session1=Treatment::session(['treatment_plan_item_id'=>$endoItem,'dentist_id'=>$dentist,'date'=>date('Y-m-d'),'time'=>'09:00','objective'=>'Primera sesión ficticia','tooth_state_end'=>'Conducto localizado, sin dolor']);
check('Primera sesión numerada 1',fn()=>(int)DB::one('SELECT session_number FROM treatment_sessions WHERE id=?',[$session1])['session_number']===1);
$session2=Treatment::session(['treatment_plan_item_id'=>$endoItem,'dentist_id'=>$dentist,'date'=>date('Y-m-d'),'time'=>'10:00','objective'=>'Segunda sesión ficticia']);
check('Sesiones del mismo tratamiento se numeran consecutivamente',fn()=>(int)DB::one('SELECT session_number FROM treatment_sessions WHERE id=?',[$session2])['session_number']===2);
check('Resumen de sesión anterior disponible al abrir una nueva',fn()=>Treatment::detail($endoItem)['sessions'][0]['id']===$session2 && Treatment::detail($endoItem)['sessions'][1]['tooth_state_end']==='Conducto localizado, sin dolor');
check('Profesional inactivo rechazado en sesión',fn()=>rejects(fn()=>Treatment::session(['treatment_plan_item_id'=>$endoItem,'dentist_id'=>999999,'date'=>date('Y-m-d'),'time'=>'09:00'])));
check('Sesión futura rechazada',fn()=>rejects(fn()=>Treatment::session(['treatment_plan_item_id'=>$endoItem,'dentist_id'=>$dentist,'date'=>date('Y-m-d',strtotime('+5 days')),'time'=>'09:00'])));
Treatment::clinicalStatus(['id'=>$endoItem,'clinical_status'=>'in_progress','reason'=>'Inicio de tratamiento ficticio']);
check('Estado clínico cambia y se guarda la razón en el historial',fn()=>(bool)DB::one('SELECT id FROM treatment_status_history WHERE treatment_plan_item_id=? AND to_status="in_progress" AND reason=?',[$endoItem,'Inicio de tratamiento ficticio']));
check('Estado de facturación no se altera por el cambio clínico',fn()=>DB::one('SELECT status FROM treatment_plan_items WHERE id=?',[$endoItem])['status']==='planned');
check('Estado clínico inválido rechazado',fn()=>rejects(fn()=>Treatment::clinicalStatus(['id'=>$endoItem,'clinical_status'=>'inventado'])));
Treatment::resolveDiagnosis(['id'=>$diag,'notes'=>'Tratado ficticiamente']);
check('Diagnóstico resuelto ya no aparece activo',fn()=>current(array_filter(Treatment::patientDiagnoses((int)DB::one('SELECT id FROM clinical_records WHERE patient_id=?',[$pid])['id']),fn($d)=>(int)$d['id']===$diag))['status']==='resolved');
check('Resolver un diagnóstico ya resuelto rechazado',fn()=>rejects(fn()=>Treatment::resolveDiagnosis(['id'=>$diag])));
