// Prescriptions: append-only like a signed clinical entry — a mistake is cancelled with a reason, never
// edited or deleted, and the financial/clinical status of the related treatment is untouched by any of it.
$rx=Prescription::create(['patient_id'=>$pid,'dentist_id'=>$dentist,'treatment_plan_item_id'=>$endoItem,'diagnosis_summary'=>'Dolor postoperatorio ficticio','instructions'=>'Reposo relativo 24 horas.','drug_name'=>['Amoxicilina','Ibuprofeno'],'presentation'=>['Cápsula 500 mg','Tableta 400 mg'],'dosage'=>['1 cápsula','1 tableta'],'frequency'=>['cada 8 horas','cada 8 horas si hay dolor'],'duration'=>['7 días','3 días'],'route'=>['oral','oral'],'item_instructions'=>['Tomar con alimentos','']]);
check('Receta creada con sus medicamentos en orden',fn()=>Prescription::detail($rx)['items'][0]['drug_name']==='Amoxicilina' && Prescription::detail($rx)['items'][1]['drug_name']==='Ibuprofeno' && count(Prescription::detail($rx)['items'])===2);
check('Receta vinculada al tratamiento aparece en su detalle',fn()=>(int)Prescription::detail($rx)['prescription']['treatment_plan_item_id']===$endoItem);
check('Receta activa por defecto',fn()=>Prescription::detail($rx)['prescription']['status']==='active');
check('Fila de medicamento vacía se descarta sin romper la receta',function() use($pid,$dentist){$id=Prescription::create(['patient_id'=>$pid,'dentist_id'=>$dentist,'drug_name'=>['','Paracetamol'],'dosage'=>['','1 tableta'],'frequency'=>['','cada 6 horas']]);return count(Prescription::detail($id)['items'])===1;});
check('Receta sin medicamentos rechazada',fn()=>rejects(fn()=>Prescription::create(['patient_id'=>$pid,'dentist_id'=>$dentist,'drug_name'=>['   '],'dosage'=>[''],'frequency'=>['']])));
check('Medicamento sin dosis rechazado',fn()=>rejects(fn()=>Prescription::create(['patient_id'=>$pid,'dentist_id'=>$dentist,'drug_name'=>['Amoxicilina'],'dosage'=>[''],'frequency'=>['cada 8 horas']])));
check('Profesional inactivo rechazado en receta',fn()=>rejects(fn()=>Prescription::create(['patient_id'=>$pid,'dentist_id'=>999999,'drug_name'=>['Amoxicilina'],'dosage'=>['1 cápsula'],'frequency'=>['cada 8 horas']])));
check('Tratamiento de otro paciente rechazado en receta',function() use($dentist,$endoItem){$otherPatient=Clinic::patient(['first_name'=>'Otro','last_name'=>'Paciente Ficticio','document'=>'TEST-OTRO-RX','phone'=>'TEST','status'=>'active']);return rejects(fn()=>Prescription::create(['patient_id'=>$otherPatient,'dentist_id'=>$dentist,'treatment_plan_item_id'=>$endoItem,'drug_name'=>['Amoxicilina'],'dosage'=>['1'],'frequency'=>['8h']]));});
Prescription::cancel(['id'=>$rx,'cancel_reason'=>'Paciente reportó alergia, prueba ficticia']);
check('Receta anulada conserva el motivo y queda trazada',fn()=>Prescription::detail($rx)['prescription']['status']==='cancelled' && Prescription::detail($rx)['prescription']['cancel_reason']==='Paciente reportó alergia, prueba ficticia');
check('Anular una receta ya anulada rechazado',fn()=>rejects(fn()=>Prescription::cancel(['id'=>$rx,'cancel_reason'=>'Otra vez'])));
check('Receta inexistente no tiene detalle',fn()=>Prescription::detail(999999)===null);
check('Listado del paciente incluye activas y anuladas',fn()=>count(array_filter(Prescription::forPatient($pid),fn($p)=>(int)$p['id']===$rx))===1);
check('Auditoría de recetas registrada',function(){$actions=array_column(DB::all('SELECT DISTINCT action FROM audit_logs'),'action');return !array_diff(['prescription_issued','prescription_cancelled'],$actions);});
